def _open_local(state: Path | str | None) -> AppRuntime:
    """Open the state dir as its single owner; refuse by name, never a traceback (I7)."""
    lock = StateDirLock(state) if state is not None else None
    try:
        if lock is not None:
            lock.acquire()
        runtime = AppRuntime.from_env(state_dir=state)
    except (StateDirLocked, StateLogCorrupt) as exc:
        if lock is not None:
            lock.release()
        label = "StateLogCorrupt: " if isinstance(exc, StateLogCorrupt) else ""
        typer.echo(f"{label}{exc}", err=True)
        raise typer.Exit(code=1) from None
    if lock is not None:
        runtime.own(lock.release)
    return runtime

